func MessageBrokerStreamSubjects() []string {
	return []string{
		EvSubjBroadcast,
		EvSubjNotice,
		EvSubjRoomUpdate,
	}
}

func evSubjPageIndex(userID string) []string {
	if userID == "" {
		return []string{
			EvSubjBroadcast,
		}
	}
	return []string{
		EvSubjBroadcast,
		"notice." + subject.Encode(userID),
	}
}

func evSubjPageRoom(userID string, subjCalcID string) []string {
	if userID == "" {
		return []string{}
	}
	return []string{
		"room.update." + subject.Encode(userID) + ".*." + subject.Encode(subjCalcID),
	}
}

