type dispatcherEventNotice struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventNotice) Dispatch(e dpapp.EventNotice) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventNotice) DispatchCtx(
	ctx context.Context, e dpapp.EventNotice,
) error {
	if e.Recipient == "" {
		return errors.New("EventNotice.Recipient must not be empty")
	}
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventNotice JSON: %w", err)
	}
	subj := "notice." + subject.Encode(string(e.Recipient))
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, subj, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", subj, err)
	}
	return nil
}

type dispatcherEventBroadcast struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventBroadcast) Dispatch(e dpapp.EventBroadcast) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventBroadcast) DispatchCtx(
	ctx context.Context, e dpapp.EventBroadcast,
) error {
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventBroadcast JSON: %w", err)
	}
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, EvSubjBroadcast, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", EvSubjBroadcast, err)
	}
	return nil
}

type dispatcherEventRoomUpdate struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventRoomUpdate) Dispatch(e dpapp.EventRoomUpdate) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventRoomUpdate) DispatchCtx(
	ctx context.Context, e dpapp.EventRoomUpdate,
) error {
	if e.Recipient == "" {
		return errors.New("EventRoomUpdate.Recipient must not be empty")
	}
	if e.Room == "" {
		return errors.New("EventRoomUpdate.Room must not be empty")
	}
	if e.Calc == "" {
		return errors.New("EventRoomUpdate.Calc must not be empty")
	}
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventRoomUpdate JSON: %w", err)
	}
	subj := "room.update." + subject.Encode(string(e.Recipient)) + "." + subject.Encode(string(e.Room)) + "." + subject.Encode(string(e.Calc))
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, subj, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", subj, err)
	}
	return nil
}
